import * as React from 'react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Toggle } from '@/components/ui/toggle';

function DropdownMenuWithToggleTrigger({
  triggerLabel,
  children,
}: Readonly<{
  triggerLabel: React.ReactNode;
  children: React.ReactNode;
}>) {
  const [open, setOpen] = React.useState(false);
  return (
    <DropdownMenu open={open} onOpenChange={setOpen}>
      <DropdownMenuTrigger asChild>
        <Toggle
          variant="outline"
          pressed={open}
          onPressedChange={setOpen}
          className="data-[state=open]:bg-fill-active data-[state=open]:text-fg-primary-inverse data-[state=open]:border-stroke-active-inverse data-[state=open]:border-2">
          {triggerLabel}
        </Toggle>
      </DropdownMenuTrigger>

      {children}
    </DropdownMenu>
  );
}

